const data = $json;

// Handle array or object
const item = Array.isArray(data) ? data[0] : data;

// Get GPT response
let text =
  item?.candidates?.[0]?.content?.parts?.[0]?.text ??
  item?.Text ??
  item?.text ??
  item?.output ??
  item?.response ??
  null;

// If no response, return empty result
if (!text) {
  return {
    moments: []
  };
}

// Convert to string
text = String(text).trim();

// Remove Markdown code fences
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Parse JSON first
try {
  const parsed = JSON.parse(text);

  // Remove spaces from JSON object keys recursively
  const cleanKeys = (value) => {
    if (Array.isArray(value)) {
      return value.map(cleanKeys);
    }

    if (value !== null && typeof value === "object") {
      const result = {};

      for (const [key, val] of Object.entries(value)) {
        const cleanKey = key.replace(/\s+/g, "");
        result[cleanKey] = cleanKeys(val);
      }

      return result;
    }

    return value;
  };

  const cleanedData = cleanKeys(parsed);

  return {
    moments: cleanedData
  };

} catch (error) {
  return {
    moments: [],
    raw_response: text,
    error: error.message
  };
}

